head.script:
scwin.trigger1_onclick = function(e) {
    //alert (autoComplete1.getValue());
    log = autoComplete1.getValue();
};
scwin.trigger2_onclick = function(e) {
    //alert (selectbox1.getValue());
    log1 = selectbox1.getValue();
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 autoComplete1 의 emptyItem 부분을 확인한다.
    //1. In the Source tab, check the emptyItem part of autoComplete1.
    //Verify step 1. emptyItem = 'true'
    //Test step 2. emptyValue 부분을 확인한다.
    //2. Check the emptyValue part.
    //Verify step 2. emptyValue = 'Please select 1'
    //Test step 3. selectbox1 의 emptyItem 부분을 확인한다.
    //1. In the Source tab, check the emptyItem part of autoComplete1.
    //Verify step 1. emptyItem = 'true'
    //Test step 1. Source 탭에서 autoComplete1 의 emptyItem 부분을 확인한다.
    //3. Check the emptyItem part of selectbox1.
    //Verify step 3. emptyItem = 'true'
    //Test step 4. emptyValue 부분을 확인한다.
    //4. Check the emptyValue part.
    //Verify step 4. emptyValue = 'Please select 2'
    //Test step 5. scwin.trigger1_onclick 부분을 확인한다.
    //5. Check the scwin.trigger1_onclick section.
    //Verify step 5. alert (autoComplete1.getValue ());
    //Test step 6. scwin.trigger2_onclick 부분을 확인한다.
    //6. Check the scwin.trigger2_onclick section.
    //Verify step 6. alert (selectbox1.getValue ());
    //Test step 7. 브라우저에서 autoComplete / selectbox 란을 확인한다.
    //7. In the browser, check the autoComplete / selectbox field.
    //Verify step 7. The autoComplete / selectbox field is displayed as 'empty'.
    //Test step 8. 브라우저에서 autoComplete1.getValue() 버튼을 클릭한다.
    //8. In your browser, click the autoComplete1.getValue () button.
    //Verify step 8. 'Please select 1' pop-up message is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('triger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == '선택해주세요1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 9. selectbox1.getValue() 버튼을 클릭한다
    //9. Click the selectbox1.getValue () button
    //Verify step 9. 'Please select 2' pop-up message is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('triger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log1 == '선택해주세요2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.a = [];
    for (var i = 1; i <= 8; i++) {
        a.push("test" + i);
        a.push(i);
    }
    dataList1.setData(a);
    autoComplete1.setSelectedIndex(-1);
    selectbox1.setSelectedIndex(-1);
    window.log = ""; window.log1 = "";
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
